use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        // Dimensions of results
        result.0.len() == y.len(),
        forall(|i: usize| i < y.len() ==> result.0[i].len() == x.len()),
        result.1.len() == y.len(),
        forall(|i: usize| i < y.len() ==> result.1[i].len() == x.len()),
        // Values in result.0 match x values across columns
        forall(|i: usize, j: usize| (i < y.len() && j < x.len()) ==> result.0[i][j] == x[j]),
        // Values in result.1 match y values across rows
        forall(|i: usize, j: usize| (i < y.len() && j < x.len()) ==> result.1[i][j] == y[i]),
{
    // Initialize output vectors
    let mut res_x: Vec<Vec<f32>> = Vec::new();
    let mut res_y: Vec<Vec<f32>> = Vec::new();

    let mut i: usize = 0;
    while i < y.len()
        invariant
            i <= y.len(),
            res_x.len() == i,
            res_y.len() == i,
            forall(|ii: usize| ii < i ==> res_x[ii].len() == x.len()),
            forall(|ii: usize| ii < i ==> res_y[ii].len() == x.len()),
            forall(|ii: usize, jj: usize| (ii < i && jj < x.len()) ==> res_x[ii][jj] == x[jj]),
            forall(|ii: usize, jj: usize| (ii < i && jj < x.len()) ==> res_y[ii][jj] == y[ii]),
        decreases y.len() - i,
    {
        // Build the i-th row vectors
        let mut row_x: Vec<f32> = Vec::new();
        let mut row_y: Vec<f32> = Vec::new();

        let mut j: usize = 0;
        while j < x.len()
            invariant
                j <= x.len(),
                row_x.len() == j,
                row_y.len() == j,
                forall(|jj: usize| jj < j ==> row_x[jj] == x[jj]),
                forall(|jj: usize| jj < j ==> row_y[jj] == y[i]),
            decreases x.len() - j,
        {
            row_x.push(x[j]);
            row_y.push(y[i]);
            j = j + 1;
        }

        // After inner loop: row_x and row_y have length x.len()
        assert(row_x.len() == x.len());
        assert(row_y.len() == x.len());

        res_x.push(row_x);
        res_y.push(row_y);

        i = i + 1;
    }

    // After outer loop, res_x and res_y have length y.len()
    // They satisfy the ensures clauses.

    (res_x, res_y)
}

}
